#include <cstdio>

int main() {
    int s;
    if (scanf("%d", &s) != 1) return 0;
    // dp[t] = number of codes of the current length with digit sum t.
    long long dp[37] = {1};
    for (int pos = 0; pos < 4; pos++) {
        long long next[37] = {0};
        for (int t = 0; t < 37; t++)
            for (int d = 0; d < 10; d++)
                if (t + d < 37) next[t + d] += dp[t];
        for (int t = 0; t < 37; t++) dp[t] = next[t];
    }
    printf("%lld\n", dp[s]);
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        int s = new Scanner(System.in).nextInt();
        // dp[t] = number of codes of the current length with digit sum t.
        long[] dp = new long[37];
        dp[0] = 1;
        for (int pos = 0; pos < 4; pos++) {
            long[] next = new long[37];
            for (int t = 0; t < 37; t++)
                for (int d = 0; d < 10; d++)
                    if (t + d < 37) next[t + d] += dp[t];
            dp = next;
        }
        System.out.println(dp[s]);
    }
}

